    pauldron(b, R, o) { const y = o.sh ?? o.cy - 3, x = 15 - o.rx - 2; ell(b, x, y, 3.4, 2.6, 2); ell(b, x - .5, y - 1, 2, 1.2, 3, 2); tri(b, x - 2, y - 1, x + 1, y - 2, x - 1, y - 6, 3); },
